#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Sets the GitHub Actions secrets that .github/workflows/social-posts.yml needs
# (see scripts/social/README.md). Values go straight to GitHub, never to disk.
# Re-run it and pick only LinkedIn to renew the token that expires every 60 days.

cd "$(dirname "$0")/../.."
REPO_SETTINGS="https://github.com/$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || echo timdamen/talks.timdamen.io)/settings/secrets/actions"

# Platform choice is asked in stage 1, so the total grows once it's known.
TOTAL_STAGES=1

banner "Social posts: Bluesky, X and LinkedIn secrets"

stage "Pick platforms"
say "Pick the platforms to set up now. A platform without secrets is skipped by"
say "the workflow. Pick every platform you want before the first post goes out:"
say "an announcement isn't sent to a platform you add later."
note "To renew the LinkedIn token, answer yes to LinkedIn only."
printf '\n'
DO_BLUESKY=0; DO_X=0; DO_LINKEDIN=0
confirm "Bluesky?" && DO_BLUESKY=1
confirm "X? (posting through the API may need credits or a paid plan)" && DO_X=1
confirm "LinkedIn?" && DO_LINKEDIN=1
TOTAL_STAGES=$((1 + DO_BLUESKY + DO_X * 2 + DO_LINKEDIN * 2 + 1))

# ── Bluesky ───────────────────────────────────────────────────────────────
if (( DO_BLUESKY )); then
  stage "Bluesky: app password"
  open_url "https://bsky.app/settings/app-passwords"
  step "Sign in if asked, then click 'Add App Password'."
  step "Name it 'talks.timdamen.io social posts'. Leave 'Allow access to your direct messages' off."
  step "Copy the generated password (xxxx-xxxx-xxxx-xxxx). It's shown once."
  ask BLUESKY_HANDLE "Your handle, without @ (e.g. timdamen.bsky.social or your domain):"
  ask_secret BLUESKY_APP_PASSWORD "Paste the app password:"
  BLUESKY_HANDLE="${BLUESKY_HANDLE#@}"
  if [[ -n "$BLUESKY_HANDLE" ]]; then set_secret BLUESKY_HANDLE "$BLUESKY_HANDLE"; fi
  if [[ -n "$BLUESKY_APP_PASSWORD" ]]; then set_secret BLUESKY_APP_PASSWORD "$BLUESKY_APP_PASSWORD"; fi
  pause
fi

# ── X ─────────────────────────────────────────────────────────────────────
if (( DO_X )); then
  stage "X: app with write access"
  open_url "https://developer.x.com/en/portal/dashboard"
  step "Sign in with the X account that should post. Sign up for developer access if asked."
  step "Create a project and an app inside it (or open an existing app)."
  step "On the app, open 'User authentication settings' → Set up / Edit:"
  note "    App permissions: Read and write"
  note "    Type of App: Web App, Automated App or Bot"
  note "    Callback URI and Website URL: https://talks.timdamen.io"
  step "Save."
  warn "Do this before generating the access token in the next stage, or the token is read-only."
  pause "Done? Press Enter"

  stage "X: keys and tokens"
  step "On the app, open 'Keys and tokens'."
  step "Under 'API Key and Secret' (consumer keys), click Regenerate and copy both."
  ask_secret X_API_KEY "Paste the API key:"
  ask_secret X_API_SECRET "Paste the API key secret:"
  step "Under 'Access Token and Secret', click Generate (or Regenerate) and copy both."
  note "It should say the token was created with Read and Write permissions."
  ask_secret X_ACCESS_TOKEN "Paste the access token:"
  ask_secret X_ACCESS_TOKEN_SECRET "Paste the access token secret:"
  for name in X_API_KEY X_API_SECRET X_ACCESS_TOKEN X_ACCESS_TOKEN_SECRET; do
    if [[ -n "${!name}" ]]; then set_secret "$name" "${!name}"; fi
  done
  pause
fi

# ── LinkedIn ──────────────────────────────────────────────────────────────
if (( DO_LINKEDIN )); then
  stage "LinkedIn: Page-posting app"
  say "Posts go out as the talks.timdamen.io Page, which needs the Community"
  say "Management API. LinkedIn only grants it to an app with no other products."
  say "Skip this stage if that app is already approved (for example when renewing the token)."
  open_url "https://www.linkedin.com/developers/apps/new"
  step "App name: talks.timdamen.io page posts"
  step "LinkedIn Page: talks.timdamen.io"
  step "App logo: upload public/favicons/android-chrome-512x512.png from this repo."
  step "Accept the legal agreement and click 'Create app'."
  step "On the 'Products' tab, request only 'Community Management API' and fill in the form."
  warn "LinkedIn reviews the request and replies by email. Stop here (Ctrl-C) until it's approved."
  pause "Approved? Press Enter"

  stage "LinkedIn: access token"
  open_url "https://www.linkedin.com/developers/tools/oauth/token-generator"
  step "Select the Page-posting app and tick the scope w_organization_social."
  step "Click 'Request access token', allow it, and copy the token."
  ask_secret LINKEDIN_ACCESS_TOKEN "Paste the access token:"
  if [[ -n "$LINKEDIN_ACCESS_TOKEN" ]]; then set_secret LINKEDIN_ACCESS_TOKEN "$LINKEDIN_ACCESS_TOKEN"; fi
  set_secret LINKEDIN_AUTHOR_URN "urn:li:organization:146695529"
  warn "This token expires in 60 days: $(date -v+60d '+%B %-d, %Y' 2>/dev/null || date -d '+60 days' '+%B %-d, %Y')."
  note "Put a reminder in your calendar to re-run this wizard for LinkedIn before then."
  pause
fi

# ── Check ─────────────────────────────────────────────────────────────────
stage "Check with a dry run"
say "Secrets are now in $REPO_SETTINGS"
say "A dry run on GitHub shows which platforms are 'configured' and the exact text"
say "per platform, without posting anything."
warn "The next hourly run on a weekday posts for real, at today's random slot."
if confirm "Start a dry run of the 'Social posts' workflow now?"; then
  gh workflow run social-posts.yml -f mode=dry-run
  note "Waiting for the run to appear…"
  sleep 5
  run_id=$(gh run list --workflow social-posts.yml --event workflow_dispatch -L 1 --json databaseId -q '.[0].databaseId')
  gh run watch "$run_id" >/dev/null 2>&1 || true
  printf '\n'
  gh run view "$run_id" --log | grep -F "$(printf '\tAnnounce talk updates\t')" | cut -f3- | sed -E 's/^[^ ]+ //' || true
  printf '\n'
  note "Look for '(configured)' next to each platform you set up."
  pause
fi

finish
